package com.example.rokidgeminisecretary;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;
final class StabilityOverview {
 static JSONObject snapshot(MainActivity owner)throws Exception{JSONObject workspace=ConversationWorkspace.snapshot(owner);return new JSONObject().put("schema",1).put("coherence",StabilityCoherence.compare(ConversationContinuation.ledger(owner),workspace,owner.stabilityNavigationSnapshot(),System.currentTimeMillis())).put("journal",StabilityJournal.snapshot(owner)).put("counters",StabilityMetrics.snapshot()).put("jobs",safeJobs(owner)).put("automaticReplay",false);}
 static JSONArray safeJobs(MainActivity owner)throws Exception{JSONArray raw=CancellableWork.list(owner),safe=new JSONArray();for(int i=0;i<raw.length();i++){JSONObject row=raw.getJSONObject(i);String kind=row.optString("kind"),phase=row.optString("phase");if(!kind.matches("meeting|image|video|import"))kind="unknown";if(!phase.matches("QUEUED|RUNNING|DELIVERY_ATTEMPTED|STOP_REQUESTED|COMPLETED|COMPLETED_AFTER_STOP|COMPLETED_AFTER_TIMEOUT|STOPPED|FAILED|START_UNCONFIRMED|UNCONFIRMED_AFTER_RESTART|TIMED_OUT|RESULT_UNKNOWN"))phase="UNKNOWN";safe.put(new JSONObject().put("kind",kind).put("phase",phase).put("sentRequests",Math.max(0,row.optInt("sentRequests"))));}return safe;}
 static void show(MainActivity owner){new Thread(()->{try{JSONObject data=snapshot(owner);owner.runOnUiThread(()->{if(owner.isDestroyed()||owner.isFinishing())return;LinearLayout box=new LinearLayout(owner);box.setOrientation(1);box.setPadding(20,12,20,12);TextView text=new TextView(owner);JSONObject c=data.optJSONObject("coherence");StringBuilder s=new StringBuilder("会話："+StabilityCoherence.label(c.optString("conversation"))+"\nナビ："+StabilityCoherence.label(c.optString("navigation"))+"\n\n通信復帰・再起動だけでは再送しません。結果未確認の処理は履歴・保存結果を確認してください。\n\n待機上限の目安：会話6分（15秒間隔で監視）、画像15分、取込10分、動画・会議解析45分。録音そのものの制限ではありません。\n\n最近の動作記録（本文・写真・住所・APIキーを含みません）\n");JSONArray events=data.optJSONObject("journal").optJSONArray("events");if(events==null)events=new JSONArray();for(int i=Math.max(0,events.length()-12);i<events.length();i++){JSONObject e=events.optJSONObject(i);s.append(e.optString("kind")).append(" / ").append(e.optString("phase")).append(" / ").append(e.optString("reason")).append("\n");}text.setText(s.toString());box.addView(text);ScrollView scroll=new ScrollView(owner);scroll.addView(box);new AlertDialog.Builder(owner).setTitle("安定稼働・復旧の確認").setView(scroll).setPositiveButton("閉じる",null).setNeutralButton("更新",(d,w)->show(owner)).setNegativeButton("診断をコピー",(d,w)->{((android.content.ClipboardManager)owner.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("ロキの動作診断",data.toString()));}).show();});}catch(Exception e){owner.runOnUiThread(()->{if(!owner.isDestroyed()&&!owner.isFinishing())new AlertDialog.Builder(owner).setMessage("診断を読み取れませんでした。保存済みデータは変更していません。").setPositiveButton("閉じる",null).show();});}},"StabilityOverview").start();}
 private StabilityOverview(){}
}
